#pragma once

// runtime/msl compiled into the MSL compiler (generated by embed_stdlib.cmake),
// written to the compiler's include directory on first use.
#include <cstddef>

namespace alchemy::msl::detail {

struct EmbeddedFile {
    const char* path;            // relative to runtime/msl, '/' separated
    const unsigned char* data;
    std::size_t size;
};
extern const EmbeddedFile stdlib_files[];
extern const std::size_t stdlib_file_count;

} // namespace alchemy::msl::detail
